    Bug 1977743 - Get MessageInjection out of mail/base mochitests. r=aleca

    Removing if from this one test removes the potential for weird side-effects in other tests.

    Differential Revision: https://phabricator.services.mozilla.com/D258334

diff --git a/mail/base/test/browser/browser_folderTreeQuirks.js b/mail/base/test/browser/browser_folderTreeQuirks.js
index 869915e0b26..4ef2821756e 100644
--- a/mail/base/test/browser/browser_folderTreeQuirks.js
+++ b/mail/base/test/browser/browser_folderTreeQuirks.js
@@ -8,9 +8,6 @@ const { GmailServer } = ChromeUtils.importESModule(
 const { MessageGenerator, SyntheticMessageSet } = ChromeUtils.importESModule(
   "resource://testing-common/mailnews/MessageGenerator.sys.mjs"
 );
-const { MessageInjection } = ChromeUtils.importESModule(
-  "resource://testing-common/mailnews/MessageInjection.sys.mjs"
-);
 const { PromiseTestUtils } = ChromeUtils.importESModule(
   "resource://testing-common/mailnews/PromiseTestUtils.sys.mjs"
 );
@@ -35,21 +32,13 @@ let account,
   moreButton,
   moreContext;
 const generator = new MessageGenerator();
-const messageInjection = new MessageInjection(
-  {
-    mode: "local",
-  },
-  generator
-);

 add_setup(async function () {
-  account = MailServices.accounts.accounts[0];
-  rootFolder = account.incomingServer.rootFolder.QueryInterface(
